from pathlib import Path

main_path = Path('NexusNovaAndroid/app/src/main/java/com/nexusnova/app/MainActivity.kt')
main = main_path.read_text(encoding='utf-8')

# White-flash prevention: keep the WebView surface on NexusNova dark while
# login -> dashboard navigation or IME/viewport resizing swaps documents.
old_webview = '        webView = WebView(this)\n        setContentView(webView)\n'
new_webview = '        webView = WebView(this)\n        webView.setBackgroundColor(android.graphics.Color.rgb(0, 18, 25))\n        webView.overScrollMode = android.view.View.OVER_SCROLL_NEVER\n        setContentView(webView)\n'
if new_webview not in main:
    if old_webview not in main:
        raise SystemExit('WebView dark-surface insertion point not found')
    main = main.replace(old_webview, new_webview, 1)

# Replace the old root Back behavior inserted by patch_session_restore.py with
# contextual web navigation plus a premium, native NexusNova-branded exit card.
old_back = '''    @Deprecated("Deprecated in Java")\n    override fun onBackPressed() {\n        if (this::webView.isInitialized && webView.canGoBack()) {\n            webView.goBack()\n        } else {\n            moveTaskToBack(true)\n        }\n    }\n'''
new_back = '''    @Deprecated("Deprecated in Java")\n    override fun onBackPressed() {\n        if (!this::webView.isInitialized) {\n            showNexusExitDialog()\n            return\n        }\n\n        webView.evaluateJavascript(NEXUS_SYSTEM_BACK_SCRIPT) { raw ->\n            if (isFinishing || isDestroyed) return@evaluateJavascript\n            when (raw?.trim()?.trim('"')) {\n                "handled" -> Unit\n                "missing" -> {\n                    if (webView.canGoBack()) webView.goBack() else showNexusExitDialog()\n                }\n                else -> showNexusExitDialog()\n            }\n        }\n    }\n\n    private fun showNexusExitDialog() {\n        if (isFinishing || isDestroyed) return\n\n        val density = resources.displayMetrics.density\n        fun dp(value: Int): Int = (value * density + 0.5f).toInt()\n        fun roundedGradient(colors: IntArray, radius: Float, strokeColor: Int? = null, strokeWidth: Int = 0): android.graphics.drawable.GradientDrawable {\n            return android.graphics.drawable.GradientDrawable(\n                android.graphics.drawable.GradientDrawable.Orientation.TL_BR,\n                colors\n            ).apply {\n                cornerRadius = radius\n                if (strokeColor != null && strokeWidth > 0) setStroke(strokeWidth, strokeColor)\n            }\n        }\n\n        val dialog = android.app.Dialog(this)\n        dialog.requestWindowFeature(android.view.Window.FEATURE_NO_TITLE)\n        dialog.setCancelable(true)\n        dialog.setCanceledOnTouchOutside(true)\n\n        val card = android.widget.LinearLayout(this).apply {\n            orientation = android.widget.LinearLayout.VERTICAL\n            gravity = android.view.Gravity.CENTER_HORIZONTAL\n            setPadding(dp(22), dp(22), dp(22), dp(20))\n            background = roundedGradient(\n                intArrayOf(\n                    android.graphics.Color.parseColor("#071626"),\n                    android.graphics.Color.parseColor("#0A2135")\n                ),\n                dp(26).toFloat(),\n                android.graphics.Color.parseColor("#2D5F7A"),\n                dp(1)\n            )\n            if (android.os.Build.VERSION.SDK_INT >= 21) elevation = dp(18).toFloat()\n        }\n\n        val logo = android.widget.TextView(this).apply {\n            text = "N"\n            gravity = android.view.Gravity.CENTER\n            setTextColor(android.graphics.Color.WHITE)\n            textSize = 27f\n            typeface = android.graphics.Typeface.DEFAULT_BOLD\n            background = roundedGradient(\n                intArrayOf(\n                    android.graphics.Color.parseColor("#13C9D7"),\n                    android.graphics.Color.parseColor("#176CFF")\n                ),\n                dp(18).toFloat(),\n                android.graphics.Color.parseColor("#7FE9FF"),\n                dp(1)\n            )\n        }\n        card.addView(logo, android.widget.LinearLayout.LayoutParams(dp(58), dp(58)).apply {\n            gravity = android.view.Gravity.CENTER_HORIZONTAL\n            bottomMargin = dp(12)\n        })\n\n        val eyebrow = android.widget.TextView(this).apply {\n            text = "NEXUSNOVA SYSTEM"\n            gravity = android.view.Gravity.CENTER\n            setTextColor(android.graphics.Color.parseColor("#5EE7E4"))\n            textSize = 10f\n            typeface = android.graphics.Typeface.DEFAULT_BOLD\n            letterSpacing = 0.14f\n        }\n        card.addView(eyebrow, android.widget.LinearLayout.LayoutParams(-1, -2).apply { bottomMargin = dp(5) })\n\n        val title = android.widget.TextView(this).apply {\n            text = "Exit NexusNova?"\n            gravity = android.view.Gravity.CENTER\n            setTextColor(android.graphics.Color.WHITE)\n            textSize = 22f\n            typeface = android.graphics.Typeface.DEFAULT_BOLD\n        }\n        card.addView(title, android.widget.LinearLayout.LayoutParams(-1, -2))\n\n        val message = android.widget.TextView(this).apply {\n            text = "Do you want to exit NexusNova? Your session will remain secure."\n            gravity = android.view.Gravity.CENTER\n            setTextColor(android.graphics.Color.parseColor("#A9BED0"))\n            textSize = 13f\n            setLineSpacing(0f, 1.18f)\n        }\n        card.addView(message, android.widget.LinearLayout.LayoutParams(-1, -2).apply {\n            topMargin = dp(8)\n            bottomMargin = dp(18)\n        })\n\n        val stay = android.widget.TextView(this).apply {\n            text = "STAY IN NEXUSNOVA"\n            gravity = android.view.Gravity.CENTER\n            setTextColor(android.graphics.Color.WHITE)\n            textSize = 12f\n            typeface = android.graphics.Typeface.DEFAULT_BOLD\n            isClickable = true\n            isFocusable = true\n            background = roundedGradient(\n                intArrayOf(\n                    android.graphics.Color.parseColor("#118EDC"),\n                    android.graphics.Color.parseColor("#1766F3")\n                ),\n                dp(15).toFloat(),\n                android.graphics.Color.parseColor("#6FE5FF"),\n                dp(1)\n            )\n            setOnClickListener { dialog.dismiss() }\n        }\n        card.addView(stay, android.widget.LinearLayout.LayoutParams(-1, dp(52)).apply { bottomMargin = dp(9) })\n\n        val exit = android.widget.TextView(this).apply {\n            text = "EXIT APP"\n            gravity = android.view.Gravity.CENTER\n            setTextColor(android.graphics.Color.parseColor("#FF9AA4"))\n            textSize = 12f\n            typeface = android.graphics.Typeface.DEFAULT_BOLD\n            isClickable = true\n            isFocusable = true\n            background = roundedGradient(\n                intArrayOf(\n                    android.graphics.Color.parseColor("#151B27"),\n                    android.graphics.Color.parseColor("#121724")\n                ),\n                dp(15).toFloat(),\n                android.graphics.Color.parseColor("#8A3B4B"),\n                dp(1)\n            )\n            setOnClickListener {\n                dialog.dismiss()\n                finishAndRemoveTask()\n            }\n        }\n        card.addView(exit, android.widget.LinearLayout.LayoutParams(-1, dp(48)))\n\n        dialog.setContentView(card)\n        dialog.setOnShowListener {\n            dialog.window?.apply {\n                setBackgroundDrawable(android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT))\n                addFlags(android.view.WindowManager.LayoutParams.FLAG_DIM_BEHIND)\n                attributes = attributes.apply { dimAmount = 0.72f }\n                val maxWidth = dp(430)\n                val available = resources.displayMetrics.widthPixels - dp(36)\n                setLayout(kotlin.math.min(maxWidth, available), android.view.ViewGroup.LayoutParams.WRAP_CONTENT)\n                setGravity(android.view.Gravity.CENTER)\n            }\n        }\n        dialog.show()\n    }\n'''
if new_back not in main:
    if old_back not in main:
        raise SystemExit('Old Android Back block not found for isolated UX patch')
    main = main.replace(old_back, new_back, 1)

if 'const val NEXUS_SYSTEM_BACK_SCRIPT' not in main:
    marker = '        const val BLANK_SCREEN_PROBE = """\n'
    script = '''        const val NEXUS_SYSTEM_BACK_SCRIPT = """\n            (function(){\n              try {\n                var ux = window.NexusNovaUxSimplify;\n                if (!ux || typeof ux.systemBack !== 'function') return 'missing';\n                return ux.systemBack() ? 'handled' : 'root';\n              } catch (_) {\n                return 'missing';\n              }\n            })();\n        """\n'''
    if marker not in main:
        raise SystemExit('System Back script insertion point not found')
    main = main.replace(marker, script + marker, 1)

main_path.write_text(main, encoding='utf-8')

required = [
    'webView.setBackgroundColor(android.graphics.Color.rgb(0, 18, 25))',
    'webView.overScrollMode = android.view.View.OVER_SCROLL_NEVER',
    'showNexusExitDialog()',
    'NEXUSNOVA SYSTEM',
    'STAY IN NEXUSNOVA',
    'EXIT APP',
    'NEXUS_SYSTEM_BACK_SCRIPT',
    'window.NexusNovaUxSimplify',
]
missing = [token for token in required if token not in main]
if missing:
    raise SystemExit('UX-only Android verification failed: ' + ', '.join(missing))
if 'moveTaskToBack(true)' in main:
    raise SystemExit('Immediate Android exit/background behavior survived UX-only patch')

print('Applied UX-only white-flash prevention and premium NexusNova exit dialog without touching mining/reward logic.')
